// Claude's review tests for A22 (duplicate), A23 (one-scenario files) and A24 (Log as HAR) in the panel.
// agy: do not edit this file.
import fs from 'node:fs';
import { expect, test, type Page } from '@playwright/test';
import { emptyState, type Mock, type Project, type WemockState } from '../src/core/types';
import { type FixtureServer, startFixtureServer } from './fixture/server';
import { type WemockSession, launchWemock } from './helpers';

let fixture: FixtureServer;
let session: WemockSession;

test.beforeAll(async () => {
  fixture = await startFixtureServer();
  session = await launchWemock(fixture.url);
});

test.afterAll(async () => {
  await session?.context?.close();
  await fixture?.close();
});

function mock(id: string, name: string): Mock {
  return {
    id, name, enabled: true, method: 'GET', urlPattern: `/api/${id}`,
    response: { status: 200, headers: {}, body: id, bodyEncoding: 'text', delayMs: 0 }, source: 'manual', createdAt: 0,
  };
}

function project(): Project {
  return {
    id: 'p1', name: 'site', origins: [fixture.origin], activeScenarioId: 'default',
    scenarios: [
      { id: 'default', name: 'Default', mocks: [mock('a', 'Alpha'), mock('b', 'Bravo')],
        sockets: [{ id: 's', name: 'Feed', enabled: true, kind: 'plain', urlPattern: '/ws/feed', onConnect: [], replies: [], createdAt: 0 }] },
      { id: 'x', name: 'Beta', mocks: [mock('c', 'Charlie')] },
    ],
  };
}

async function readState(): Promise<WemockState> {
  return session.worker.evaluate(async () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (await (globalThis as any).chrome.storage.local.get('wemock.state'))['wemock.state'];
  });
}

async function open(): Promise<{ page: Page; panel: Page }> {
  await session.setState({ ...emptyState(), enabledOrigins: [fixture.origin], projects: [project()] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  const tabId = await session.tabIdOf(page);
  const panel = await session.context.newPage();
  await panel.goto(`chrome-extension://${session.extensionId}/panel.html?tabId=${tabId}`);
  return { page, panel };
}

const names = async () => (await readState()).projects[0]!.scenarios.map((s) => s.name);

test('A22: Duplicate a mock opens the copy, right after the original', async () => {
  const { page, panel } = await open();
  try {
    await panel.getByTestId('tab-mocks').click();
    await panel.getByTestId('mock-row').filter({ hasText: 'Alpha' }).click();
    await panel.getByTestId('mock-duplicate').click();
    await expect(panel.getByTestId('field-name')).toHaveValue('Alpha (copy)');
    await expect.poll(async () => (await readState()).projects[0]!.scenarios[0]!.mocks.map((m) => m.name)).toEqual(['Alpha', 'Alpha (copy)', 'Bravo']);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('A22: Duplicate a socket mock', async () => {
  const { page, panel } = await open();
  try {
    await panel.getByTestId('tab-mocks').click();
    await panel.getByTestId('socket-row').first().click();
    await panel.getByTestId('socket-duplicate').click();
    await expect(panel.getByTestId('socket-name')).toHaveValue('Feed (copy)');
    await expect(panel.getByTestId('socket-row')).toHaveCount(2);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('A22: Duplicate the selected scenario, with Undo', async () => {
  const { page, panel } = await open();
  try {
    await panel.getByTestId('tab-mocks').click();
    await panel.locator('.scenario-group').filter({ hasText: 'Beta' }).locator('.scenario-group-header').click();
    await panel.getByTestId('scenario-duplicate').click();
    await expect.poll(names).toEqual(['Default', 'Beta', 'Beta (2)']);
    await expect(panel.getByTestId('undo-bar')).toBeVisible();
    await panel.getByTestId('undo').click();
    await expect.poll(names).toEqual(['Default', 'Beta']);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('A23: export one scenario, then import it as a new one', async () => {
  const { page, panel } = await open();
  try {
    await panel.getByTestId('tab-mocks').click();
    await panel.locator('.scenario-group').filter({ hasText: 'Beta' }).locator('.scenario-group-header').click();
    const dl = panel.waitForEvent('download');
    await panel.getByTestId('scenario-export').click();
    const d = await dl;
    expect(d.suggestedFilename()).toBe('wemock-Beta.json');
    const text = fs.readFileSync((await d.path())!, 'utf-8');
    expect(JSON.parse(text)).toMatchObject({ wemock: 'scenario', schemaVersion: 1, scenario: { name: 'Beta' } });

    await panel.getByTestId('import').setInputFiles({ name: 'wemock-Beta.json', mimeType: 'application/json', buffer: Buffer.from(text) });
    await expect(panel.getByTestId('import-choice')).toBeVisible();
    await expect(panel.getByTestId('import-replace')).toHaveCount(0);
    await expect(panel.getByTestId('import-add')).toHaveText('Add as a new scenario');
    await panel.getByTestId('import-add').click();
    await expect.poll(names).toEqual(['Default', 'Beta', 'Beta (2)']);
    const s = await readState();
    expect(s.projects).toHaveLength(1);
    expect(s.projects[0]!.scenarios[2]!.mocks.map((m) => m.urlPattern)).toEqual(['/api/c']);
    expect(s.projects[0]!.scenarios[2]!.mocks[0]!.id).not.toBe('c');
  } finally {
    await panel.close();
    await page.close();
  }
});

test('A24: Save HAR writes the rows shown, and it imports back', async () => {
  const { page, panel } = await open();
  try {
    await page.evaluate(async () => {
      await (await fetch('/api/goals')).text();
      await (await fetch('/api/echo', { method: 'POST', body: 'x' })).text();
    });
    await expect(panel.getByTestId('log-row')).toHaveCount(2);
    await panel.getByTestId('log-filter').fill('goals');
    const dl = panel.waitForEvent('download');
    await panel.getByTestId('log-save-har').click();
    const d = await dl;
    expect(d.suggestedFilename()).toMatch(/^wemock-.*\.har$/);
    const har = JSON.parse(fs.readFileSync((await d.path())!, 'utf-8'));
    expect(har.log.entries).toHaveLength(1);
    expect(har.log.entries[0].request.url).toContain('/api/goals');

    await panel.getByTestId('tab-mocks').click();
    await panel.getByTestId('import').setInputFiles({ name: 'log.har', mimeType: 'application/json', buffer: Buffer.from(JSON.stringify(har)) });
    await panel.getByTestId('import-add').click();
    await expect.poll(names).toEqual(['Default', 'Beta', 'HAR log.har']);
  } finally {
    await panel.close();
    await page.close();
  }
});
